#!/usr/bin/env bash
# Make the datasets of the team Drive available on the Colab runtime and link the generated files.
#
#   bash /content/XLA_SEARLE/SEARLE-main/colab/prepare_data.sh cirr circo fiq imagenet   # any subset, in any order
#
# Drive layout (folder SEARLE shared by Chi, added to "My Drive" as a shortcut; datasets already extracted):
#   $DRIVE/datasets/CIRR/        CIRR (cirr/, train/, dev/, test1/)
#   $DRIVE/datasets/CIRCO/       CIRCO (annotations/, COCO2017_unlabeled/)
#   $DRIVE/datasets/FashionIQ/   FashionIQ (captions/, image_splits/, images/)
#   $DRIVE/datasets/ImageNet1K/  ImageNet test: test/ (100,000 images) and ILSVRC2012_img_test_v10102019.tar
#   $DRIVE/outputs/{GPT_phrases,oti_pseudo_tokens,similar_concepts,phi_models}   files generated by the team
# Result:
#   /content/data/{CIRR,CIRCO,FashionIQ,ImageNet1K}
#   SEARLE-main/data/{GPT_phrases,oti_pseudo_tokens,similar_concepts,phi_models} -> $DRIVE/outputs/...
# CIRR, CIRCO and FashionIQ are linked to their Drive folders; the old CIRR.tar (truncated) and FashionIQ.tar
# (0 bytes) are only tried when the folder is missing. Image features are cached in $DRIVE/cache, so the slow
# Drive reads happen once per configuration. ImageNet is read 100,000 images at a time by the training, so its
# tar is still extracted to the local disk (one 13 GB file reads much faster than 100,000 small ones); without
# the tar the folder ImageNet1K/test is linked instead.
set -uo pipefail

[ -f /content/env.sh ] && source /content/env.sh
DRIVE=${DRIVE:-/content/drive/MyDrive/SEARLE}
DATA=${DATA:-/content/data}
SRC=${SRC:-/content/XLA_SEARLE/SEARLE-main}
DS=$DRIVE/datasets
status=0
mkdir -p "$DATA"

fail() { echo "ERROR: $*"; status=1; }

prepare_folder_dataset() {  # <name> <file that must exist inside the dataset>
  local name=$1 check=$2
  if [ -e "$DATA/$name/$check" ]; then
    echo "$name: already in $DATA/$name"
    return
  fi
  rm -rf "$DATA/$name"
  if [ -e "$DS/$name/$check" ]; then
    echo "$name: linking $DATA/$name to the folder $DS/$name"
    ln -sfn "$DS/$name" "$DATA/$name"
  elif [ -f "$DS/$name.tar" ]; then
    echo "WARNING: no folder $DS/$name, extracting $DS/$name.tar to $DATA ..."
    tar -xf "$DS/$name.tar" -C "$DATA" || { fail "cannot extract $DS/$name.tar"; return; }
  else
    fail "neither the folder $DS/$name (with $check) nor $DS/$name.tar exists"
    return
  fi
  [ -e "$DATA/$name/$check" ] && echo "$name: ready in $DATA/$name" || fail "$DATA/$name/$check missing"
}

prepare_fiq() {
  if [ -e "$DATA/FashionIQ/image_splits" ]; then
    echo "FashionIQ: already in $DATA/FashionIQ"
    return
  fi
  rm -rf "$DATA/FashionIQ"
  if [ -d "$DS/FashionIQ/image_splits" ]; then
    echo "FashionIQ: linking $DATA/FashionIQ to the folder $DS/FashionIQ"
    ln -sfn "$DS/FashionIQ" "$DATA/FashionIQ"
  elif [ -f "$DS/FashionIQ.tar" ]; then
    echo "WARNING: no folder $DS/FashionIQ, extracting $DS/FashionIQ.tar ..."
    rm -rf "$DATA/fiq_extract"
    mkdir -p "$DATA/fiq_extract"
    tar -xf "$DS/FashionIQ.tar" -C "$DATA/fiq_extract" || { fail "cannot extract FashionIQ.tar"; return; }
    local splits
    splits=$(find "$DATA/fiq_extract" -maxdepth 4 -type d -name image_splits | head -1)
    [ -n "$splits" ] || { fail "no image_splits folder inside FashionIQ.tar"; return; }
    ln -sfn "$(dirname "$splits")" "$DATA/FashionIQ"
  else
    fail "neither the folder $DS/FashionIQ (with image_splits/) nor $DS/FashionIQ.tar exists"
    return
  fi
  [ -e "$DATA/FashionIQ/image_splits" ] && echo "FashionIQ: ready in $DATA/FashionIQ ($(ls "$DATA/FashionIQ/images" | wc -l) images)" \
    || fail "$DATA/FashionIQ/image_splits missing"
}

prepare_imagenet() {
  local count
  count=$(ls "$DATA/ImageNet1K/test" 2>/dev/null | wc -l)
  if [ "$count" -ge 100000 ]; then
    echo "ImageNet1K: already in $DATA/ImageNet1K ($count test images)"
    return
  fi
  rm -rf "$DATA/ImageNet1K"
  local tarfile=$DS/ImageNet1K/ILSVRC2012_img_test_v10102019.tar
  if [ -f "$tarfile" ]; then
    echo "ImageNet1K: extracting $tarfile to the local disk (about 13 GB, several minutes) ..."
    mkdir -p "$DATA/ImageNet1K"
    tar -xf "$tarfile" -C "$DATA/ImageNet1K" || fail "cannot extract the ImageNet tar"
  elif [ -d "$DS/ImageNet1K/test" ]; then
    echo "WARNING: $tarfile not found, linking $DATA/ImageNet1K to the folder $DS/ImageNet1K" \
         "(reading 100,000 images from Drive is slow: train with --features-cache-dir)"
    ln -sfn "$DS/ImageNet1K" "$DATA/ImageNet1K"
  else
    fail "neither $tarfile nor the folder $DS/ImageNet1K/test exists"
    return
  fi
  count=$(ls "$DATA/ImageNet1K/test" 2>/dev/null | wc -l)
  [ "$count" -eq 100000 ] && echo "ImageNet1K: ready ($count test images)" \
    || fail "expected 100000 images in $DATA/ImageNet1K/test, found $count"
}

[ -d "$DRIVE" ] || { echo "ERROR: $DRIVE not found: mount Drive (cell 1) and add the SEARLE shortcut to My Drive"; exit 1; }

for name in "$@"; do
  case "$name" in
    cirr) prepare_folder_dataset CIRR cirr/captions/cap.rc2.val.json ;;
    circo) prepare_folder_dataset CIRCO annotations/val.json ;;
    fiq|fashioniq) prepare_fiq ;;
    imagenet) prepare_imagenet ;;
    *) fail "unknown dataset '$name' (use cirr, circo, fiq, imagenet)" ;;
  esac
done

# Files generated by the team (GPT phrases, concepts, OTI tokens, phi checkpoints) stay on Drive
mkdir -p "$SRC/data"
for d in GPT_phrases oti_pseudo_tokens similar_concepts phi_models; do
  link="$SRC/data/$d"
  if [ -L "$link" ] || [ ! -e "$link" ]; then
    mkdir -p "$DRIVE/outputs/$d"
    ln -sfn "$DRIVE/outputs/$d" "$link"
  else
    echo "WARNING: $link is a real folder, left unchanged"
  fi
done
echo "Linked $SRC/data/{GPT_phrases,oti_pseudo_tokens,similar_concepts,phi_models} -> $DRIVE/outputs/"
df -h /content | tail -1 | awk '{print "Local disk: " $4 " free of " $2}'
exit $status
